To determine whether a graph is bipartite, we can use a breadth-first search (BFS) starting from each unvisited vertex to explore all connected components and determine if they could form an odd cycle. Here's a Python code to solve this problem:

```python
import sys

def bfs(graph, start, visited):
    queue = [start]
    visited[start] = True
    groups = [start]

    while queue:
        node = queue.pop(0)
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
                groups.append(neighbor)

    return groups

def find_bipartite(graph, queries):
    n = len(graph)
    visited = [False] * n

    for i in range(n):
        if not visited[i]:
            groups = bfs(graph, i, visited)
            for group in groups:
                yield group

    for q in queries:
        query = set(q)
        if not query:
            continue

        for group in find_bipartite(graph, query):
            for node in group:
                yield 1
            break

    yield 0

def main():
    n = int(input())

    # Example graph with edges
    graph = [
        [3],
        [0, 2],
        [0, 1, 2, 4],
        [1, 2, 4],
        [0, 1, 3, 4]
    ]

    queries = [
        (4, 1), (1, 3), (3, 2), (2, 4), (2, 4), (2, 3), (1, 4), (2, 4),
        (1, 2), (2, 4), (3, 2), (1, 2), (2, 4), (1, 4), (3, 4)
    ]

    for query in queries:
        yield from find_bipartite(graph, query)

if __name__ == "__main__":
    main()
