import sys
from collections import defaultdict

def find_max_profit(n, k, special_vertices, c, costs, edges):
    # Build adjacency list for the graph
    graph = defaultdict(list)
    for v1, v2 in edges:
        graph[v1].append(v2)
        graph[v2].append(v1)

    # Initialize the answer array
    max_profit = [0] * n

    # Calculate the shortest path for each edge to all special vertices and record in distance matrix
    distance = [[sys.maxsize] * n for _ in range(n * 2)]
    for i in range(n):
        distance[i] = [sys.maxsize] * (n + 1)
        distance[i][i] = 0

    def dijkstra(start):
        queue = [(0, start)]
        visited = [False] * n
        while queue:
            dist, curr = queue.pop(0)
            if visited[curr]:
                continue
            visited[curr] = True
            for neighbor in graph[curr]:
                new_dist = dist + costs[neighbor - 1]
                if new_dist < distance[curr][neighbor % (n + 1)]:
                    distance[curr][neighbor % (n + 1)] = new_dist
                    queue.append((new_dist, neighbor))

    for idx in range(n):
        if idx not in special_vertices:
            dijkstra(idx)

    def find_shortest_path(from_vertex, to_vertex):
        return distance[from_vertex][to_vertex % (n + 1)]

    # Loop to calculate the max profit for each vertex
    for i in range(k):
        current_saturated = special_vertices[i]
        for j in range(i + 1, k):
            if special_vertices[j] != current_saturated:
                profit_from_i = find_profit(current_saturated)
                profit_from_j = find_profit(special_vertices[j])
                if profit_from_j > profit_from_i:
                    max_profit[current_saturated - 1] = max(max_profit[current_saturated - 1], profit_from_j)
                else:
                    max_profit[current_saturated - 1] = max(max_profit[current_saturated - 1], profit_from_i)

    return max_profit

def find_profit(vertex):
    for j in range(1, n + 1):
        if vertex != j and vertex - j <= costs[j - 1] and distance[vertex][j] >= distance[vertex][vertex - j]:
            for k in range(i, j):
                if distance[vertex][k] < costs[k + i - 1]:
                    distance[vertex][j] = distance[vertex][k]
    return sum(distance[vertex][range(n+1)]) - sum(distance[vertex][range(i, n)])

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    n, m, k = map(int, data[0:3])
    special_vertices = [int(data[i]) - 1 for i in range(3, 3 + k)]
    c = [int(data[i]) for i in range(3 + k, 3 + k + n)]
    costs = [int(data[i]) for i in range(3 + k + n, 3 + k + n + m)]
    edges = [[int(data[i]) - 1, int(data[i + 1]) - 1] for i in range(m)]
    print(*find_max_profit(n, k, special_vertices, c, costs, edges))
