def euler_totient(n):
    res = [1]
    for p in range(2, int(n**0.5)+1):
        if n % p == 0:
            for q in range(p*n, n+1, p):
                res.append(p*(n // p**2) // (p-1))
            while n % p == 0:
                n //= p
