from collections import defaultdict
from typing import List

def min_flips(password: List[int], targets: List[int], operations: List[int]) -> int:
    n = len(password)
    panel_to_index = defaultdict(list)
    for i, panel in enumerate(password):
        panel_to_index[panel].append(i)

    for i, target in enumerate(targets):
        if operation_target(panel_to_index, target, operations):
            return i

    return -1

def operation_target(panel_to_index: dict[int, List[int]], target: int, operations: List[int]) -> bool:
    for operation in operations:
        for idx in panel_to_index[operation]:
            if idx < target - 2 or idx > target + 2:
                if (idx - target) % 2 == 1:
                    return False
            else:
                if (idx - target) % 2 == 1:
                    return True
    return False

