class ChipShiftSolver:
    def __init__(self, board):
        self.board = board
        self.operations = []
        self.directions = {'L': 0, 'R': 1, 'U': -1, 'D': 1}

    def find_sequence(self):
        operations = []
        for i in range(6):
            for j in range(6):
                if self.board[i][j] == '0' and j < 5:
                    if self.board[i][j+1] == '1':
                        if i < 5:
                            directions = {self.directions['L']: i, self.directions['R']: 5 - i}
                            if directions['R'] < directions['L']:
                                if self.find_sequence_candidates(directions['R'], self.board, i, j, operations):
                                    self.insert_operation("L", i)
                            else:
                                if self.find_sequence_candidates(directions['L'], self.board, i, j, operations):
                                    self.insert_operation("R", 5 - i)
                        else:
                            if self.find_sequence_candidates(directions['R'], self.board, i, j, operations):
                                self.insert_operation("R", 5 - i)
                    elif self.board[i][j] == '9':
                        if i < 5:
                            directions = {self.directions['U']: i, self.directions['D']: 5 - i}
                            if directions['D'] < directions['U']:
                                if self.find_sequence_candidates(directions['U'], self.board, i, j, operations):
                                    self.insert_operation("U", i)
                            else:
                                if self.find_sequence_candidates(directions['D'], self.board, i, j, operations):
                                    self.insert_operation("D", 5 - i)
                        else:
                            if self.find_sequence_candidates(directions['U'], self.board, i, j, operations):
                                self.insert_operation("U", i)

    def find_sequence_candidates(self, direction, board, current_row, current_col, operations):
        if self.board[current_row + direction][current_col] in "0123456789ABCDEF":
            if self.board[current_row + direction][current_col] >= self.board[current_row][current_col]:
                return True
        return False

    def insert_operation(self, direction, index):
        operations.append(f"{direction} {index}")

    def solve_puzzle(self):
        self.find_sequence()
        if len(self.operations) == 0:
            return "No solution found."
        return len(self.operations), self.operations

