from heapq import heappush, heappop

def optimal_travel_time(station, time, costs, next_time, max_t, penalty):
    queue = [(0, time, station, costs[station], True)]
    visited = {station: None}

    while queue:
        cost, t, last, c, fin = heappop(queue)
        if t == max_t:
            if cost + 1 <= penalty:
                return cost
            else:
                return None
        if last == station:
            continue
        for i in range(station + 1, station + 1 + time):
            if i not in visited:
                new_cost = cost + c[i] if not fin else cost + 1
                if next_time[i] < t:
                    new_cost -= costs[i][min(next_time[i], t-100)]
                next_cost = min(next_cost, new_cost)
                next_time = min(next_time, new_cost < penalty)
                if next_cost is None and next_time is None:
                    return None
                if next_time:
                    next_t = t - next_time[i]
                else:
                    next_t = time - int(next_time[i] * 100000 // t)
                visited[i] = last
                heappush(queue, (new_cost, next_t, i, costs[i], fin))
        if last not in visited:
            visited[last] = -1
        while queue and visited[visited[queue[0][2]]] != last:
            heappop(queue)
    return penalty if not cost else min(cost, penalty)

