from collections import defaultdict

def domino_photos(n, m, tiling):
    # Create a grid to mark which cells have been visited
    visited = [[False] * m for _ in range(n)]
    move_dir = {"L": (0, -1), "R": (0, 1), "D": (-1, 0), "U": (1, 0)}

    def is_valid_move(dx, dy):
        return 0 <= dx < n and 0 <= dy < m and visited[dx][dy] and tiling[dx][dy] != "."

    def update_visited(dx, dy):
        visited[dx][dy] = True
        for direction in move_dir:
            x, y = dx + move_dir[direction][0], dy + move_dir[direction][1]
            if is_valid_move(x, y):
                update_visited(x, y)

    photo_ids = set()
    for dx in range(n):
        for dy in range(m):
            if tiling[dx][dy] in {"L", "R"} and visited[dx][dy - 1] and visited[dx][dy + 1]:
                clone = [line[:]+line[1:] for line in tiling]
                clone[dx][dy], clone[dx][dy + 1] = clone[dx][dy-1], clone[dx][dy]
                update_visited(dx, dy - 1)
                update_visited(dx, dy + 1)
                photo_id = "".join(clone)
                photo_ids.add(photo_id)

    return len(photo_ids)

