    cache = defaultdict(lambda: 0)

    def inner(cached, x, y):
        # Base case if valid bounds, if by any means we already have value, use it, else calculate and cache it
        if (x, y) not in cache:
            if x + y > m:
                return 0
            else:
                new_cached = cached + (x + y + 1)
                cache[(x, y)] = new_cached
                return new_cached
        return cache[(x, y)]

    return sum(inner([-1] * (n + m)) + inner(inner(sum_S(n-1, m, a), x, y) for y in range(m) for x in range(n))) - sum_S(n, m, a)

