def count_exchange_left_and_right(snapshots, free_cells, num_left):
    count = 0
    for free, open in zip(free_cells, snapshots):
        left = len(free) - num_left
        if free - open >= 0:
            removed = free - open
            count += left * removed
        else:
            remaining = abs(free - open)
            if max(0, remaining - left) % 2 != 0:
                count += left + remaining - left
    return count
