# Function to find cycle of odd length
def find_odd_cycle(graph):
    def is_odd_cycle(cycle):
        for i in range(1, len(cycle)):
            if (cycle[i] in graph[cycle[i-1]] or
                cycle[i-1] in graph[cycle[i]]):
                return False
        return True

    # DFS to find odd cycle
    def dfs(node, visited, cycle):
        if node in visited:
            if is_odd_cycle(cycle + [node]):
                return cycle
        else:
            visited.add(node)
            cycle.append(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    find_odd_cycle(graph, len(cycle), cycle)

    def dfs_init():
        node = 1
        visited = set()
        cycle = []
        while node not in visited:
            found = False
            for neighbor in graph[node]:
                if neighbor not in visited:
                    cycle = dfs(node, visited, cycle + [neighbor])
                    found = True
                    break
            if not found:
                cycle = dfs(node, visited, cycle)
            if is_odd_cycle(cycle):
                return cycle
        cycle = []
        dfs_init()

    if len(graph[1]):
        return dfs_init()
    else:
        return None

