def is_bipartite(graph):
    color = [0] * len(graph)  # Initialize color array
    color[0] = 1  # Assign color 1 to the first vertex

    for vertex in range(len(graph)):
        if color[vertex] == 0:
            queue = [vertex]
            color[vertex] = 1  # Assign color 1 to this vertex
            while queue:
                new_vertex = queue.pop(0)
                for neighbor in graph[new_vertex]:
                    if color[neighbor] == 0:
                        queue.append(neighbor)
                        color[neighbor] = -color[new_vertex]  # Assign opposite color
                    elif color[neighbor] == color[new_vertex]:
                        return False  # Cycle found
    return True

