    answers = [[-1, -1] * n for _ in range(n)]
    for i, value in enumerate(a):
        answers[value - 1][0] = i
    for i in range(n):
        value = a[i]
        for j in range(i, n):
            if j - i + 1 <= k and value <= j and answers[value - 1][0] > j:
                answers[value - 1][0] = j
            elif j - i + 1 > k:
                break

    swapper = a.copy()
    for i in range(k, 0, -1):
        cnt = Counter()
        for j in range(n):
            ind = findMaxContiguous(answers, i - 1, max(cnt.keys()) or 0)
            cnt[j] = ind
            swapper[ind] = j
        for j, index in enumerate(swapper):
            a[j] = index

    presi = 0
    for count in Counter(a).values():
        presi += count // k
    for count in Counter(a).values():
        presi += min(count % k, 1)
