def is_correct_order(puzzle):
    correct_order = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    for i in range(6):
        for j in range(6):
            if correct_order.index(puzzle[i][j]) > correct_order.index(puzzle[(i + 1) % 6][j]):
                return False
    return True

# Function to perform a cyclic shift of the rows
def cyclic_shift_rows(puzzle, row):
    return puzzle[row % 6][:5] + puzzle[row % 6][5:], row

# Function to perform a cyclic shift of the columns
def cyclic_shift_columns(puzzle, col):
    flat = ''.join(puzzle[i][col-1] for i in range(6))
    shifted = flat[-1:] + flat[:-1]
    return [shifted, col % 6]

