from typing import List

def find_ghd(n: int, nums: List[int]) -> int:
    def check(n, k):
        count = {}
        for num in nums:
            if num & (k - 1):
                return False
            if k in count:
                count[k] += 1
            else:
                count[k] = 1
        return sum(count.values()) >= len(nums) // 2

    def binary_search(start, end):
        while start < end - 1:
            mid = (start + end) // 2
            if check(mid, mid):
                start = mid
            else:
                end = mid
        return end

    lower_bound = binary_search(1, 10**18)
    upper_bound = 2 * lower_bound
    return binary_search(lower_bound, upper_bound)

